+        let Some(&x) = XS.iter().min_by(|a, b| (m.to.x - **a).abs().total_cmp(&(m.to.x - **b).abs())) else {
+            continue;
+        };
+        if out.last() != Some(&x) {
+            out.push(x);
+        }
+    }
