+    let reply = s.handle(&msg).expect("a request gets a response");
+    let result = &reply["result"];
+    if result["isError"] == json!(true) {
+        Err(result["content"][0]["text"].as_str().unwrap_or_default().to_owned())
+    } else {
+        Ok(result["structuredContent"].clone())
+    }
