+fn params(side: WireSide, start: (f64, f64)) -> WireParams {
+    WireParams {
+        wire_diameter: 0.25,
+        gap: 0.04,
+        condition: "C110".into(),
+        side,
+        start: Some(Point2::new(start.0, start.1)),
+        plane_z: -12.0,
+        tabs: None,
+        stock: None,
+        clearance: 1.0,
+        sharp_corners: false,
+    }
+}
